"""Assemble research/FINAL_RESEARCH_REPORT.md from stored results. Numbers are pulled from result files; prose states only what those support."""
import csv
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from research.phase8 import aggregate as A   # noqa: E402

R = ROOT / "research"
f3 = lambda x: f"{x:.3f}"
tbl = lambda h, rs: "\n".join(["| " + " | ".join(h) + " |", "|" + "---|" * len(h)] + ["| " + " | ".join(map(str, r)) + " |" for r in rs])
runs = {p: A.latest(p).name for p in A.PHASE_DIRS}
hr = A.headline_ranking()
pairs = {}
for ph in ("phase3", "phase4"):
    for r in csv.DictReader(open(A.latest(ph) / "paired_comparisons.csv")):
        pairs[(r["metric"], r["A"], r["B"])] = r


def pr(metric, a, b):
    r = pairs.get((metric, a, b))
    if r:
        return dict(d=float(r["mean_diff"]), lo=float(r["ci95_low"]), hi=float(r["ci95_high"]), p=float(r["p_holm"]), w=int(r["wins"]), l=int(r["losses"]), n=int(r["n"]))
    r = pairs.get((metric, b, a))
    if r:
        return dict(d=-float(r["mean_diff"]), lo=-float(r["ci95_high"]), hi=-float(r["ci95_low"]), p=float(r["p_holm"]), w=int(r["losses"]), l=int(r["wins"]), n=int(r["n"]))
    return None


def prs(metric, a, b):
    x = pr(metric, a, b)
    return "not computed" if not x else f"{x['d']:+.3f} (95% CI {x['lo']:+.3f} to {x['hi']:+.3f}; Holm p = {x['p']:.3g}; {a} better on {x['w']} / worse on {x['l']} of {x['n']} seeds)"


P5 = A.load("phase5", "analysis.json")
EV = A.load("phase5", "evolution_analysis.json")
P6 = A.load("phase6", "analysis.json")
P7S = A.load("phase7", "oracle_summary.json")
P7C = A.load("phase7", "db_security_checks.json")
P7P = A.load("phase7", "scalability.json")
Q7 = A.load("phase7", "q40_vs_python.json")
man = {p: json.load(open(A.latest(p) / "run_manifest.json")) for p in A.PHASE_DIRS}
nseeds = hr["q40"]["nDCG@5"]["n"]
order = ["random", "degree_centrality", "communication_frequency", "pagerank", "spatial_proximity", "q40", "q40_r", "raeer"]
head = tbl(["Method", "P@1", "P@5", "R@5", "MRR", "nDCG@5", "MAP"], [[m, *[f"{hr[m][k]['mean']:.3f} [{hr[m][k]['lo']:.3f}, {hr[m][k]['hi']:.3f}]" if k in hr[m] else "–" for k in ("P@1", "P@5", "R@5", "MRR", "nDCG@5", "AP")]] for m in order if m in hr])
abl = P5["ablation"]["clean"]["means"]
full = abl["raeer"]["nDCG@5"]["mean"]
abl_rows = sorted([(k.replace("raeer-no_", ""), abl[k]["nDCG@5"]["mean"] - full) for k in abl if k.startswith("raeer-no_")], key=lambda x: x[1])
rob = P5["robustness"]
top_level = {k: max(v, key=float) for k, v in rob.items()}
wins = [k for k in rob if rob[k][top_level[k]]["raeer"]["nDCG@5"]["mean"] > rob[k][top_level[k]]["q40_py"]["nDCG@5"]["mean"]]
ra = P6["retrieval"]["ALL"]; an = P6["answer"]["ALL"]; ea = P6["error_attribution"]["ALL"]
sc = sorted(P7P["scales"], key=int)
slow = sorted(P7P["scales"][sc[-1]]["latency"].items(), key=lambda kv: -kv[1].get("p95_ms", 0))[:3]
tot7 = sum(v["comparisons"] for v in P7S.values()); mm7 = sum(v["mismatches"] for v in P7S.values())
imp = EV["impact_detection"]

S = []
add = lambda *x: S.extend(x)
add("# CrimeMind: An Explainable, Evidence-Evolution-Aware AI Framework for Multisource Criminal Investigation and Investigative Lead Prioritization",
    "", "**Final research report (Phases 3–8).** All results are on *synthetic* data generated by the project's own generator. No statement here is a claim about real investigations, real offenders or real-world accuracy.", "",
    "Source runs: " + "; ".join(f"{p} `{r}`" for p, r in runs.items()) + ". Regenerate with `python -m research.run_all` (see `research/docs/EXECUTION_GUIDE.md`).", "")
add("## 1. Abstract", "",
    f"CrimeMind is a decision-support prototype that ranks investigative leads over multisource case data (communications, locations, transactions, relationships, evidence) with explicit evidence validity. We evaluate it on {nseeds} generated cities (2 cases each) with independently stored ground truth. A frozen SQL baseline (Q40) is compared with five simple baselines, a reliability-aware variant (Q40-R) and a new method, RAEER, that adds provenance-independent evidence accumulation, spatio-temporal consistency, relational support and contradiction handling. "
    f"On the synthetic benchmark RAEER reaches nDCG@5 {hr['raeer']['nDCG@5']['mean']:.3f} against {hr['q40']['nDCG@5']['mean']:.3f} for Q40 and {hr['spatial_proximity']['nDCG@5']['mean']:.3f} for spatial proximity; ablations show most of the gain comes from the spatial feature and contradiction handling, and we explain why the result is coupled to the generator and should not be generalised. The study also covers perturbation robustness, evidence evolution through an append-only validity log, an evidence-retrieval benchmark (541 questions), a verified SQL layer (independent oracles, security and scalability checks) and states what was **not** run (no live LLM was evaluated).", "")
add("## 2. Executive summary", "",
    f"* **Ranking.** Q40 beats random and the simple baselines on nDCG@5; against spatial proximity its nDCG@5 advantage is statistically detectable but MRR is not, spatial proximity is better on P@5/R@5, and the ordering is not robust to tie bounds (Phase 3 report). Q40 − spatial = {prs('nDCG@5', 'q40', 'spatial_proximity')}.",
    f"* **RAEER.** RAEER − Q40 on nDCG@5 = {prs('nDCG@5', 'raeer', 'q40')}. This is a large effect on synthetic data whose generator plants the contradictions RAEER looks for (Section 28).",
    f"* **Ablation.** Removing the spatial feature changes RAEER nDCG@5 by {dict(abl_rows)['spatial']:+.3f}; contradiction handling by {dict(abl_rows)['contradiction']:+.3f}; most other components show no detectable effect on clean data, and removing independence/provenance handling slightly *raises* clean nDCG@5 (see Section 17).",
    f"* **Robustness.** RAEER stays above Q40 at the highest perturbation level in {len(wins)} of {len(rob)} perturbation types.",
    f"* **Evidence evolution.** {EV['steps']} lifecycle steps over {EV['cases']} cases applied with 0 integrity failures; no must-not-flag finding was flagged; expected-flag recall at the first dispute of an item was {imp['first_dispute_step']['recall']:.1%} ({imp['first_dispute_step']['detected']}/{imp['first_dispute_step']['expected_findings']}) and {imp.get('later_steps', {}).get('recall', float('nan')):.1%} for later transitions.",
    f"* **Retrieval / answers.** Full retrieval MRR {ra['full']['MRR']['mean']:.3f}, coverage@8 {ra['full']['coverage@8']['mean']:.3f} (random MRR {ra['random']['MRR']['mean']:.3f}); answers from the offline template provider only. Gemini and Anthropic evaluations are **NOT RUN** (no credentials).",
    f"* **SQL layer.** {tot7 - mm7}/{tot7} oracle comparisons agree (after two defects found by the oracles were fixed); {sum(c['result'] == 'PASS' for c in P7C)}/{len(P7C)} database/security checks pass.", "")
add("## 3. Introduction", "", "Investigators face large, heterogeneous and partly unreliable records. Decision-support tools are only useful if they are transparent about *why* a lead is surfaced, honest about uncertainty, and able to react when evidence is later challenged or superseded. CrimeMind is a prototype built around those requirements: SQL-first analysis, explicit evidence lifecycle, auditability, and an optional language-model layer that may only restate retrieved facts.", "")
add("## 4. Problem statement", "", "Given a case with recorded entities, events, communications, observations, transactions, relationships and evidence of varying reliability, produce an ordered list of persons whose records warrant human attention, with an explanation per lead, and keep that list consistent as the validity of evidence changes. Scores are heuristics for prioritising review; they are not probabilities of guilt.", "")
add("## 5. Research questions and hypotheses", "",
    "1. RQ1: How does the frozen Q40 baseline compare with simple baselines under a common, tie-aware protocol? (No directional hypothesis was fixed in advance beyond Q40 ≥ random.)",
    "2. RQ2: Does using evidence reliability and independence (Q40-R, RAEER) improve ranking, and which components matter?",
    "3. RQ3: How robust are the methods to degraded or conflicting evidence?",
    "4. RQ4: Does the evidence-lifecycle machinery flag affected findings and update rankings correctly?",
    "5. RQ5: Can evidence be retrieved for natural-language questions, and what do answers cost in groundedness?",
    "6. RQ6: Are the SQL modules correct, safe and scalable?", "",
    "RQ2's hypothesis (reliability-aware ≥ baseline) was stated before Phase 4 and RAEER's configuration was frozen before evaluation (`frozen_before_evaluation: true` in `phase4_config.json`); the *design* of RAEER was, however, informed by knowledge of the generator (Section 28).", "")
add("## 6. Related work", "", "**Requires literature verification.** This section deliberately contains no citations. Topics a verified review must cover: evaluation metrics for ranked retrieval (precision/recall at K, MRR, nDCG, average precision); graph centrality and PageRank-style ranking; BM25 lexical retrieval; noisy-OR evidence combination; paired non-parametric testing (Wilcoxon signed-rank), bootstrap confidence intervals and multiple-comparison correction (Holm); link analysis and network methods in criminal-intelligence analysis; evidence reliability grading in intelligence practice; retrieval-augmented generation and grounded answer evaluation; synthetic-data evaluation pitfalls. No reference has been checked by the authors.", "")
add("## 7. System overview", "", "FastAPI + PostgreSQL 16 + React. Eighteen read-only, versioned SQL modules answer 40 registered investigation questions. Evidence has a four-state validity lifecycle (SUPPORTED, CHALLENGED, INVALIDATED, SUPERSEDED) written only through `change_validity()` into an append-only event log; findings that depend on changed evidence are flagged for recomputation. Access is case-scoped, the application role cannot read the ground-truth schema, and queries are audited. An optional AI layer retrieves evidence (BM25 with entity and reference boosts), builds an allowed-identifier context, and validates every answer.", "")
add("## 8. Synthetic data and generator", "", f"Fifty datasets (seeds 2026–2075), each with two cases, are generated deterministically; their SHA-256 content hashes are stored in `research/seed_manifest.csv` and re-verified every time a workspace is rebuilt. Storylines plant perpetrators, accomplices, red herrings, supporting and conflicting evidence, and lifecycle changes. The data are fictional; any resemblance to real persons is coincidental.", "")
add("## 9. Ground truth and independence", "", "Ground truth (roles and intended lifecycle steps) lives in a separate schema/file that ranking algorithms never receive; algorithms see a `CaseView` without it, and the application role cannot read it (checked, SEC-01/02). Phase 5 expectations for lifecycle steps were authored in three tiers (must-flag, must-not-flag, indeterminate) separately from the code under test. Independence is procedural, not organisational: the same author wrote generator, methods and evaluation.", "")
add("## 10. Evaluation protocol and metrics", "", "Unit of analysis: the seed (mean of its two cases; n = 50). Relevant = grade ≥ 1 (perpetrator 3, accomplice 2); nDCG gain 2^g − 1; P@K uses denominator K. Unlabelled candidates are excluded, not counted negative. Common tie rule: descending raw score, then ascending SHA-256 of (dataset, case, candidate); optimistic and pessimistic tie bounds are reported. Statistics: 10 000-resample bootstrap CIs with a fixed seed, paired Wilcoxon signed-rank, matched-pairs rank-biserial and Cohen's d_z, Holm correction within metric.", "")
add("## 11. Baselines", "", "Random; communication frequency; spatial proximity to the scene at incident time; degree centrality and PageRank over the case graph (plus a victim-personalised PageRank reported as an extra); frozen Q40 through an adapter that assigns 0 to unscored candidates. Every method ranks the same candidate set.", "")
add("## 12. Frozen Q40", "", f"Q40 is module M18 variant `overall`: weighted binary signals (spatial 0.35, temporal 0.10, communication 0.15, financial 0.15, relational 0.10, evidence 0.15; evidence = min(1, independent origins/3); 60-minute window). It is not modified; its SQL hash is recorded in the frozen baseline bundle. Phase 7 verified that an independent Python statement of Q40 reproduces its scores exactly on every case tested (max |difference| = {max(q['max_abs_score_diff'] for q in Q7)}).", "")
add("## 13. Q40-R and RAEER", "", "**Q40-R** keeps Q40's six signals, weights and window but multiplies each signal by a reliability factor (reliability score × status factor: SUPPORTED 1, CHALLENGED 0.5, INVALIDATED/SUPERSEDED 0; missing reliability 0.5). With reliability off it equals frozen Q40 (tested). **RAEER** (Reliability-Aware Evidence Evolution Ranking) uses the same weights but computes each signal from noisy-OR accumulation over independent origins, a 150 m scene radius, exponential temporal decay (τ = 30 min), relational support towards the victim or scene persons, a location-conflict contradiction rule (D = 1000 m, γ = 0.5) and corroboration. The definition is our operational one (`research/phase4/docs/RAEER_DEFINITION.md`); parameters are not tuned.", "")
add("## 14. Results — baseline comparison (Phase 3)", "", head, "",
    f"Q40 vs spatial proximity: nDCG@5 {prs('nDCG@5', 'q40', 'spatial_proximity')}; MRR {prs('MRR', 'q40', 'spatial_proximity')}. Spatial proximity has higher P@5/R@5. Under optimistic/pessimistic tie bounds the Q40–spatial ordering is not robust (Phase 3 report). Graph baselines beat random, probably because the generator plants ASSOCIATE relationships around perpetrators (a confound, not evidence that graph centrality finds offenders).", "")
add("## 15. Results — Q40-R and RAEER (Phase 4)", "",
    f"Q40-R − Q40, nDCG@5: {prs('nDCG@5', 'q40_r', 'q40')}. Part of this is tie resolution (Q40 has few distinct scores), not reliability evidence. RAEER − Q40: nDCG@5 {prs('nDCG@5', 'raeer', 'q40')}; MRR {prs('MRR', 'raeer', 'q40')}; P@1 {prs('P@1', 'raeer', 'q40')}. RAEER − spatial proximity: nDCG@5 {prs('nDCG@5', 'raeer', 'spatial_proximity')}.", "")
add("## 16. Stratified results", "", "Strata (reliability, contradiction, evidence type) are in `research/phase4/results/<run>/strata.json` and the Phase 4 report. They come from the same bundled change as the headline result and carry the same caveat; they were not used to select any parameter.", "")
add("## 17. Ablation", "", tbl(["Removed component", "Δ nDCG@5 vs full RAEER"], [[k, f"{v:+.3f}"] for k, v in abl_rows]), "", f"Full RAEER nDCG@5 = {full:.3f} on clean data. Components with no detectable effect on clean data may still matter under perturbation or in real data; this ablation cannot say.", "")
add("## 18. Robustness", "", "Thirteen seeded perturbation types at three levels (Phase 5 report). RAEER's nDCG@5 at the highest level versus Q40:", "",
    tbl(["Perturbation", "Level", "RAEER", "Q40", "Δ"], [[k, top_level[k], f3(rob[k][top_level[k]]['raeer']['nDCG@5']['mean']), f3(rob[k][top_level[k]]['q40_py']['nDCG@5']['mean']), f"{rob[k][top_level[k]]['raeer']['nDCG@5']['mean'] - rob[k][top_level[k]]['q40_py']['nDCG@5']['mean']:+.3f}"] for k in rob]), "",
    "Random status perturbations measure the loss of usable evidence, not lifecycle correctness. `delayed_evidence` degrades all methods.", "")
add("## 19. Sensitivity", "", "RAEER parameters (radius, τ, γ, D, weights) were varied one at a time (`sensitivity` in the Phase 5 analysis). Weights are robust; the scene radius is the sensitive parameter (a 50 m radius lowers nDCG@5 by 0.17), which matters because the radius was set by us, not learned.", "")
add("## 20. Evidence evolution", "", f"{EV['steps']} lifecycle steps over {EV['cases']} cases, applied through the system's own `change_validity()`. Integrity: {EV['integrity']['history_ok_cases']}/{EV['cases']} cases with intact history, {EV['integrity']['transition_checks_failed_total']} failed transition checks. Impact detection against independently authored expectations: all steps {imp['all_steps']['recall']:.1%} recall ({imp['all_steps']['detected']}/{imp['all_steps']['expected_findings']}), first dispute of an item {imp['first_dispute_step']['recall']:.1%}; later transitions of the same evidence were never flagged (0 recall). The cause was not investigated; a plausible but untested explanation is that the affected findings are already marked for recomputation. This needs review and should not be read as a success. Must-not-flag findings flagged: {imp['all_steps']['must_not_flag_findings_flagged']}. Latency per step (p50): apply {EV['latency_ms']['apply_ms']['p50']:.1f} ms, recompute {EV['latency_ms']['recompute_ms']['p50']:.1f} ms, rank {EV['latency_ms']['rank_ms_per_method']['p50']:.1f} ms per method.", "")
add("## 21. Evidence retrieval", "", tbl(["Variant", "R@5", "MRR", "nDCG@5", "coverage@8"], [[v, f3(d["R@5"]["mean"]), f3(d["MRR"]["mean"]), f3(d["nDCG@5"]["mean"]), f3(d["coverage@8"]["mean"])] for v, d in ra.items()]), "",
    "Retrieval is lexical (BM25 with entity and reference boosts and typo tolerance), not embedding-based. Typo tolerance accounts for the gain over plain BM25 on this benchmark; the boosts had negligible effect. Multi-hop and SQL-investigation questions are weakest. No new retrieval mechanism was added.", "")
add("## 22. LLM answer evaluation", "", f"**Live LLM providers: NOT RUN** (no API credentials in the research environment). The harness (timeouts, bounded retries, rate-limit handling, token/latency recording) exists and is tested with a mocked transport, which is a code-path test, not a provider result. Template-provider answers: valid {an['valid']['mean']:.3f}, hallucination {an['hallucination']['mean']:.3f}, groundedness {an['groundedness']['mean']:.3f}, citation completeness {an['citation_completeness']['mean']:.3f}, citation correctness {an['citation_correctness']['mean']:.3f}, correct refusal {an['correct_refusal']['mean']:.3f}. Error attribution on all questions: {', '.join(f'{k} {v}' for k, v in ea.items())}. These numbers describe the deterministic template, not a language model.", "")
add("## 23. SQL module verification", "", f"{tot7} comparisons of {len(P7S)} module variants against independent Python oracles on four committed datasets and on mutated edge-case databases: {tot7 - mm7} match, {mm7} differ. Oracles do not exist for M18 `evidence_strength`, `connected_both`, `multi_domain` (Q40 is covered separately).", "")
add("## 24. Database correctness and security", "", f"{sum(c['result'] == 'PASS' for c in P7C)} of {len(P7C)} checks pass: constraints, append-only history, lifecycle consistency, audit mirroring, rollback, 8-thread concurrent validity changes, least-privilege role (no ground-truth access, no direct evidence writes), case isolation, and injection-style hostile parameters. HTTP-level authentication/authorisation is covered by the backend test-suite.", "")
add("## 25. Scalability", "", f"Replicating one case up to {sc[-1]}x ({P7P['scales'][sc[-1]]['table_rows']['communications']} communications) on a 2-vCPU container: slowest p95 latencies at {sc[-1]}x were " + "; ".join(f"{k} {v['p95_ms']} ms" for k, v in slow) + ". No candidate index gave a gain distinguishable from the measurement noise floor, so none was added. The model is synthetic and indicative only.", "")
add("## 26. Defects found by the evaluation", "", "1. *Answer validator rejected valid answers* quoting contradiction summaries with location codes (found by the Phase 6 benchmark; 18% of answers affected before the fix, regression-tested).", "2. *M8 `around` ranked entities with unknown location above confirmed ones* (NULL ordering; found by the Phase 7 oracle; module v1.1).", "3. *NUL byte in an identifier caused an unhandled driver error* (found by the Phase 7 injection check; regression-tested).", "", "Earlier evidence for 1 and 2 is preserved (`phase6/results/P6-20261101T133558Z-7be8caa`, `phase7/results/bugevidence_M8_prefix`).", "")
add("## 27. Statistical considerations", "", "Seeds are the independent units; the two cases of a seed share a generator draw and are averaged. Holm correction is applied within each metric over all method pairs. Bootstrap intervals use 10 000 resamples with a fixed seed. Effects are reported with intervals and win/loss counts, not p-values alone. Many comparisons were examined; unadjusted exploratory results in the phase reports are labelled as such.", "")
add("## 28. Threats to validity", "", "* **Generator coupling (most important).** RAEER's contradiction and temporal rules exploit structures the generator plants (incident-time presence of true leads, independent alibi evidence for red herrings). A different generator, or real data, may remove the advantage.", "* **Researcher knowledge.** The same person built generator, methods and evaluation; RAEER's design was informed by the generator even though its parameters were frozen before evaluation.", "* **Single generator family**, 50 seeds, one city model.", "* **Baseline strength.** Simple baselines are plain implementations, not tuned.", "* **Benchmark construction.** Retrieval questions are templated from ground truth; annotation independence is procedural.", "* **Tie handling** affects Q40-family comparisons; bounds are reported.", "* **Oracles** were written by the author of the SQL.", "")
add("## 29. Limitations", "", "No real data; no human-factors study; no live-LLM results; heuristic reliability weights; scene radius and decay constants set by hand; contradiction handling limited to structured location conflicts (free-text witness contradictions are not processed); lexical retrieval only; synthetic scalability model; HTTP security tested at unit level only.", "")
add("## 30. Ethics and responsible use", "", "All people in the data are fictional. Rankings are review-prioritisation heuristics, never findings of guilt; outputs carry that statement. Real deployment would require lawful authority, bias and fairness evaluation on real populations, human oversight, and audit — none of which this study provides. Presenting RAEER's synthetic performance as real-world accuracy would be misleading.", "")
add("## 31. Conclusions and future work", "", "A transparent, evidence-lifecycle-aware pipeline can be built and verified end-to-end, and on synthetic data reliability- and contradiction-aware scoring ranks planted leads well above the frozen baseline and simple alternatives. The result is conditional on the generator. Next steps: a second, independently written generator; blind annotation of the benchmark by a different person; live-LLM evaluation with credentials; free-text contradiction handling; calibration of reliability weights on real (or expert-labelled) material; and expert review of the explanations.", "")
add("## Appendix A. Reproducibility", "", "`python -m research.run_all --phases 3 4 5 6 7 8` regenerates every result in this report; `--quick` runs a reduced smoke configuration to a scratch directory. Each run writes a manifest (run ID, git commit, environment, dataset hashes, configs, status). See `research/docs/REPRODUCIBILITY_GUIDE.md` and `research/phase8/results/<run>/results_index.md`.", "")
add("## Appendix B. Run manifests", "", tbl(["Phase", "Run ID", "Git commit"], [[p, runs[p], man[p].get("git_commit") or man[p].get("environment", {}).get("git_commit")] for p in runs]), "")
(R / "FINAL_RESEARCH_REPORT.md").write_text("\n".join(S), encoding="utf-8")
print("wrote", R / "FINAL_RESEARCH_REPORT.md", len("\n".join(S)))
